+using Microsoft.EntityFrameworkCore;
+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Client.Services;
+using ShipmentTracker.Data;
+
+namespace ShipmentTracker.Services;
+
+public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
+{
+    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
+    {
+        return await db.Shipments
+            .OrderByDescending(s => s.CreatedAt)
+            .Select(s => MapToDto(s))
+            .ToListAsync();
+    }
+
+    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
+    {
+        var shipment = await db.Shipments
+            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+        return shipment is null ? null : MapToDto(shipment);
+    }
+
+    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync(string customerId)
+    {
+        return await db.Shipments
+            .Where(s => s.CustomerId == customerId)
+            .OrderByDescending(s => s.CreatedAt)
+            .Select(s => MapToDto(s))
+            .ToListAsync();
+    }
+
+    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
+    {
+        var shipment = new Shipment
+        {
+            TrackingNumber = $"TRK-{Guid.NewGuid().ToString("N")[..8].ToUpper()}",
+            Origin = dto.Origin,
+            Destination = dto.Destination,
+            Status = ShipmentStatus.Pending,
+            CreatedAt = DateTime.UtcNow,
+            EstimatedDelivery = dto.EstimatedDelivery,
+            CustomerId = dto.CustomerId,
+            Description = dto.Description
+        };
+
+        db.Shipments.Add(shipment);
+        await db.SaveChangesAsync();
+        return MapToDto(shipment);
+    }
+
+    public async Task UpdateStatusAsync(UpdateShipmentStatusDto dto)
+    {
+        var shipment = await db.Shipments.FindAsync(dto.Id);
+        if (shipment is null) return;
+
+        if (Enum.TryParse<ShipmentStatus>(dto.Status, true, out var status))
+        {
+            shipment.Status = status;
+            await db.SaveChangesAsync();
+        }
+    }
+
+    private static ShipmentDto MapToDto(Shipment s) => new()
+    {
+        Id = s.Id,
+        TrackingNumber = s.TrackingNumber,
+        Origin = s.Origin,
+        Destination = s.Destination,
+        Status = s.Status.ToString(),
+        CreatedAt = s.CreatedAt,
+        EstimatedDelivery = s.EstimatedDelivery,
+        CustomerId = s.CustomerId,
+        Description = s.Description
+    };
+}
