@page "/dispatch"
@attribute [Authorize]
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Dispatch Dashboard</h1>

<div class="mb-3 d-flex gap-3 align-items-end">
    <div>
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="statusFilter">
            <option value="">All</option>
            <option value="Pending">Pending</option>
            <option value="PickedUp">Picked Up</option>
            <option value="InTransit">In Transit</option>
            <option value="OutForDelivery">Out for Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Exception">Exception</option>
        </select>
    </div>
    <div>
        <button class="btn btn-primary" @onclick="ToggleCreateForm">
            @(showCreateForm ? "Cancel" : "Create Shipment")
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-3 p-3">
        <h5>New Shipment</h5>
        <div class="row g-2">
            <div class="col-md-3">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-3">
                <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
            </div>
            <div class="col-md-2">
                <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
            </div>
            <div class="col-md-1">
                <button class="btn btn-success" @onclick="CreateShipment">Add</button>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-info">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                @onchange="(e) => UpdateStatus(shipment.Id, e.Value?.ToString() ?? string.Empty)">
                            <option value="">Change status...</option>
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Exception">Exception</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string statusFilter = "";
    private bool showCreateForm;
    private CreateShipmentDto newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrEmpty(statusFilter)
            ? shipments ?? []
            : (shipments ?? []).Where(s => s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleCreateForm() => showCreateForm = !showCreateForm;

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        showCreateForm = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(int id, string status)
    {
        if (string.IsNullOrEmpty(status)) return;
        await ShipmentService.UpdateStatusAsync(new UpdateShipmentStatusDto { Id = id, Status = status });
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }
}

@page "/track"
@attribute [Authorize]
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Shipment</h1>

<div class="mb-3 d-flex gap-2">
    <input class="form-control" style="max-width:300px" placeholder="Enter tracking number"
           @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

@if (shipment is not null)
{
    <div class="card p-4">
        <h4>@shipment.TrackingNumber</h4>
        <p><strong>Description:</strong> @(shipment.Description ?? "N/A")</p>
        <p><strong>Origin:</strong> @shipment.Origin</p>
        <p><strong>Destination:</strong> @shipment.Destination</p>
        <p><strong>Status:</strong> <span class="badge bg-info fs-6">@shipment.Status</span></p>
        <p><strong>Created:</strong> @shipment.CreatedAt.ToString("yyyy-MM-dd HH:mm")</p>
        <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "TBD")</p>

        <h5 class="mt-4">Progress</h5>
        <div class="d-flex justify-content-between position-relative mt-2 mb-3">
            @foreach (var step in statusSteps)
            {
                var isActive = GetStatusIndex(shipment.Status) >= statusSteps.IndexOf(step);
                <div class="text-center" style="flex:1">
                    <div class="rounded-circle mx-auto @(isActive ? "bg-success" : "bg-secondary")"
                         style="width:24px;height:24px"></div>
                    <small class="d-block mt-1">@step</small>
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private ShipmentDto? shipment;
    private bool searched;

    private List<string> statusSteps = ["Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered"];

    private int GetStatusIndex(string status) => statusSteps.IndexOf(status);

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }
}

